package com.subhamviky.settlement.generated;

import java.util.Map;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ThreadLocalRandom;
import java.util.function.Supplier;

/**
 * settlement-service — NFR module (generated by A2C CodeGenAgent).
 * Circuit breaker, retry with jittered backoff, an idempotency claim store
 * contract, the health path and graceful shutdown registration.
 */
public final class NfrSupport {

    public static final String HEALTH_PATH = "/actuator/health";

    private NfrSupport() {
    }

    /** closed -> open after N consecutive failures -> half-open after the reset window. */
    public static final class CircuitBreaker {
        private final int failureThreshold;
        private final long resetMillis;
        private int failures;
        private long openedAt = -1;

        public CircuitBreaker(int failureThreshold, long resetMillis) {
            this.failureThreshold = failureThreshold;
            this.resetMillis = resetMillis;
        }

        public synchronized boolean allow() {
            return openedAt < 0 || System.currentTimeMillis() - openedAt >= resetMillis;
        }

        public synchronized void recordSuccess() {
            failures = 0;
            openedAt = -1;
        }

        public synchronized void recordFailure() {
            failures++;
            if (failures >= failureThreshold) {
                openedAt = System.currentTimeMillis();
            }
        }

        public synchronized String state() {
            return openedAt < 0 ? "closed" : (allow() ? "half_open" : "open");
        }
    }

    public static final class CircuitOpenException extends RuntimeException {
        public CircuitOpenException(String message) {
            super(message);
        }
    }

    /** Run the action behind the breaker with jittered exponential backoff retry. */
    public static <T> T retryWithBackoff(Supplier<T> action, CircuitBreaker breaker, int retries,
                                         long baseDelayMillis) {
        int attempt = 0;
        while (true) {
            if (!breaker.allow()) {
                throw new CircuitOpenException("circuit open");
            }
            try {
                T result = action.get();
                breaker.recordSuccess();
                return result;
            } catch (RuntimeException e) {
                breaker.recordFailure();
                attempt++;
                if (attempt > retries) {
                    throw e;
                }
                long delay = (long) (baseDelayMillis * Math.pow(2, attempt - 1)
                        * (0.5 + ThreadLocalRandom.current().nextDouble()));
                try {
                    Thread.sleep(delay);
                } catch (InterruptedException interrupted) {
                    Thread.currentThread().interrupt();
                    throw e;
                }
            }
        }
    }

    /** Idempotency claim contract: claim once per (tenant, requestId), then complete. */
    public interface IdempotencyStore {
        boolean claim(String tenantId, String requestId);

        void complete(String tenantId, String requestId, Map<String, Object> result);

        Optional<Map<String, Object>> result(String tenantId, String requestId);

        void release(String tenantId, String requestId);
    }

    /** Single-node store for tests and local runs; production binds a database-backed one. */
    public static final class InMemoryIdempotencyStore implements IdempotencyStore {
        private final Map<String, Map<String, Object>> records = new ConcurrentHashMap<>();
        private static final Map<String, Object> IN_PROGRESS = Map.of();

        @Override
        public boolean claim(String tenantId, String requestId) {
            return records.putIfAbsent(tenantId + ":" + requestId, IN_PROGRESS) == null;
        }

        @Override
        public void complete(String tenantId, String requestId, Map<String, Object> result) {
            records.put(tenantId + ":" + requestId, Map.copyOf(result));
        }

        @Override
        public Optional<Map<String, Object>> result(String tenantId, String requestId) {
            Map<String, Object> value = records.get(tenantId + ":" + requestId);
            return value == null || value.isEmpty() ? Optional.empty() : Optional.of(value);
        }

        @Override
        public void release(String tenantId, String requestId) {
            records.remove(tenantId + ":" + requestId, IN_PROGRESS);
        }
    }

    /** Run the callback on JVM shutdown (SIGTERM from the container runtime). */
    public static void registerGracefulShutdown(Runnable onShutdown) {
        Runtime.getRuntime().addShutdownHook(new Thread(onShutdown, "graceful-shutdown"));
    }
}
